}

// ---- text helpers ----
function normalizeBreaks(s){
  // Convert <br>, <br/>, and encoded &lt;br&gt; (incl. spacing) to real newlines BEFORE escaping
  return String(s || '')
    .replace(/(?:<\s*br\s*\/?\s*>|&lt;\s*br\s*\/?\s*&gt;)/gi, '\n')
    .replace(/\r\n/g, '\n'); // unify CRLF
}
// 1) Normalize <br>→\n first
// 2) Keep raw newlines; render with CSS pre-line (no <br> in HTML)
// 3) Light “widont”: replace last space with NBSP so single-word 3rd lines are rarer.
function widont(seg) {
  return String(seg).replace(/\s+([^\s]{1,12})$/u, '\u00A0$1');
}
function formatText(raw){
  const s = normalizeBreaks(raw);
  return s.split(/\n/).map(v => widont(v.trim())).join('\n');
}
function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, (m) => (
    {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[m]
  ));
}

// ---- minimal preload helper (only when using <img> layers) ----
function preloadHTML(urls){
  const uniq = Array.from(new Set((urls || []).filter(u => typeof u === 'string' && u)));
  if (!uniq.length) return '';
  const imgs = uniq.map(u => `<img src="${u}" width="1" height="1" alt="" loading="eager" decoding="sync" fetchpriority="high">`).join('');
  return `<div class="__preloads" style="position:absolute;left:-9999px;top:-9999px;width:1px;height:1px;overflow:hidden;opacity:0;visibility:hidden;">${imgs}</div>`;
}

// ---- background/overlay layer emitters (CSS bg vs <img> toggle) ----
function bgLayerHTML(url){
  if (!url) return '';
  if (!useImgBackgrounds) {
    return `<div class="page-bg" style="background-image:url('${url}');"></div>`;
  }
  return `<div class="page-bg"><img src="${url}" alt="" loading="eager" decoding="sync" fetchpriority="high" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;"></div>`;
}
function overlayLayerHTML(url){
  if (!url) return '';
  if (!useImgBackgrounds) {
    return `<div class="page-overlay" style="background-image:url('${url}');"></div>`;
  }
  return `<div class="page-overlay"><img src="${url}" alt="" loading="eager" decoding="sync" fetchpriority="high" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;"></div>`;
}

