// Prefer array from Phase-2; else extract each <div class="book-page" ...>...</div> from pages_html
function extractFragmentsFromPagesHtml(src) {
  const html = String(src || '');
  const re = /<div\s+class=(['"])book-page\1[^>]*>[\s\S]*?<\/div>/gi;
  const out = [];
  let m;
  while ((m = re.exec(html)) !== null) {
    out.push(m[0]);
  }
  // If none matched, fallback to whole string (so we don't silently drop content)
  return out.length ? out : (html.trim() ? [html] : []);
}

