  // Get ONE generator item just to learn the base directory
  const gen0 = ($items('Generate Page Preview Images', 0, 0)?.[0]?.json) ?? {};
  const poll0 = ($items('Poll PDFMonkey Image until ready', 0, 0)?.[0]?.json) ?? {};

  // Binary property name (usually "data")
  const binKey = Object.keys(item.binary || {})[0] || 'data';
  const binMeta = item.binary?.[binKey] || {};

  // Use the actual filename from the HTTP download (e.g., "p14.png")
  const fileName = binMeta.fileName || gen0.pageImageFilename || 'p00.png';

  // Derive the target directory for preview images
  // Prefer an explicit key if you have it, otherwise strip filename from p00 key.
  let dir = '';
  if (gen0.pageImageR2Dir) {
    dir = gen0.pageImageR2Dir;
  } else if (gen0.pageImageR2Key && gen0.pageImageR2Key.includes('/')) {
    dir = gen0.pageImageR2Key.split('/').slice(0, -1).join('/');
  } else if (gen0.orderR2BaseKey) {
    dir = `${gen0.orderR2BaseKey}/preview-images`;
  }

  const pageImageR2Key = dir ? `${dir}/${fileName}` : fileName;

  return {
    json: {
      ...gen0,
      ...poll0,
      pageImageFilename: fileName,
      pageImageR2Key
    },
    binary: item.binary
  };
});
